steps.run:
$archive = Join-Path $env:RUNNER_TEMP 'intellij-python-3.13.5.zip'
$directory = Join-Path $env:RUNNER_TEMP 'intellij-python-3.13.5'
Expand-Archive -LiteralPath $archive -DestinationPath $directory -ErrorAction Stop
Push-Location -LiteralPath $directory -ErrorAction Stop
try { & .\setup.ps1 } finally { Pop-Location }
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$cache = if ($env:AGENT_TOOLSDIRECTORY) { $env:AGENT_TOOLSDIRECTORY } else { $env:RUNNER_TOOL_CACHE }
$python = Join-Path $cache 'Python\3.13.5\x64\python.exe'
if (!(Test-Path -LiteralPath (Join-Path $cache 'Python\3.13.5\x64.complete'))) { throw 'Python tool cache is incomplete' }
if ((& $python --version) -ne 'Python 3.13.5') { throw 'Python version mismatch' }

$env:LSF_IDE_PYTHON = (Get-Command python).Source
cmd.exe /d /c tools\intellij.cmd help
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
python tools/intellij.py run website-prepare
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
git diff --exit-code
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
